export async function demo(flag: boolean, items: string[]) {
  let result = await corpus.echo("start");
  if (flag) { result = await corpus.echo("yes"); } else { result = "no"; }
  if (result === "a") { result = "b"; } else if (result === "c") { result = "d"; } else {}
  const both = await corpus.echo(await corpus.echo("inner"));
  try { result = await corpus.echo("try"); }
  catch (error) { result = "caught"; }
  finally { await corpus.echo("finally"); }
  for (const item of items) { await corpus.echo(item); }
  while (flag) { flag = false; }
  return [result, both];
}
